  rows.forEach((r, i) => { const y = padT + i * rowH, bh = Math.min(18, rowH * 0.56), yb = y + (rowH - bh) / 2; const fill = r.hi ? 'var(--h-hl, var(--s2))' : 'var(--muted-mark)';
    h += '<g class="vmark' + selC(o.sel, i) + '" data-i="' + i + '"' + tipA(r.c, [[o.vname || 'Değer', V.fmt(r.v, o.fmt)]], o.tipx ? o.tipx(i) : null) + ' tabindex="0"><rect x="0" y="' + y + '" width="' + Wd + '" height="' + rowH + '" fill="transparent"/>' + T(padL - 8, y + rowH / 2 + 4, String(r.c).length > 22 ? String(r.c).slice(0, 21) + '…' : r.c, 'vt vcat' + (r.hi ? ' hst-b' : ''), 'end') + '<rect x="' + padL + '" y="' + yb.toFixed(1) + '" width="' + Math.max(1, X(r.v || 0) - padL).toFixed(1) + '" height="' + bh.toFixed(1) + '" rx="3" fill="' + fill + '"/>' + T((o.ref != null && Math.abs(X(r.v || 0) - X(o.ref)) < 46 ? Math.max(X(r.v || 0), X(o.ref)) : X(r.v || 0)) + 6, y + rowH / 2 + 4, r.lab != null ? r.lab : V.fmt(r.v, o.fmt, true), 'vt ' + (r.hi ? 'hst-hl2' : 'vlab')) + '</g>'; });
  if (o.ref != null) { const x = X(o.ref); h += '<line x1="' + x.toFixed(1) + '" x2="' + x.toFixed(1) + '" y1="' + (padT - 6) + '" y2="' + (H - 4) + '" class="hst-ref"/>' + T(x, padT - 10, o.refLabel || 'Hedef', 'vt hst-ns', 'middle'); }
  return h + '</svg>';
