  const bw = (Wd - pl - pr) / n, gw = bw * 0.62; const Y = v => pt + (H - pt - pb) * (1 - Math.max(0, v) / mx);
  let h = '<svg class="viz hst" viewBox="0 0 ' + Wd + ' ' + H + '" width="' + Wd + '" role="img" aria-label="' + esc(o.label || 'Vurgulu sütun grafik') + '"><line x1="' + pl + '" x2="' + (Wd - pr) + '" y1="' + Y(0) + '" y2="' + Y(0) + '" class="vbase"/>';
