const kpiM = (id, title, icon, m, o) => { o = o || {}; return { id, span: 3, title, type: 'Kart (yeni)', style: 'm-half', morder: o.morder, wells: { 'Değer': '[' + m + ']', 'Referans etiketi': 'Geçen yıl' }, measures: [m], format: ['Açıklama değeri 24 pt; telefonda iki kart yan yana', 'Etiket kısa (en çok 2 kelime)'], why: o.why || 'Sahada bir bakışta okunacak tek sayı; fark rozeti yönü verir.',
  render: a => { const v = a.M('[' + m + ']'); const p = a.M(gyX(m)); return a.V.kpicard({ v, fmt: o.fmt, delta: o.pp ? pp(v, p) : rel(v, p), deltaFmt: o.pp ? 'pp' : undefined, invert: o.invert, dlabel: 'GY', icon, spark: o.spark === false ? null : monthly(a, m), W: 120 }); } }; };
const repTip = (a, add, cat) => { const s = a.Q([a.timeAxis], ['Net Satış'], { add, totals: false, noRls: true }); return { title: cat, cards: [['Net satış', a.fmt(a.M('[Net Satış]', { add }), 'para', true)], ['Hedefe göre', (() => { const v = a.M('[Net Satış]', { add }), t = a.M('[Temsilci Hedefi]', { add, extraMeasures: REP_HEDEF }); return isNum(v) && isNum(t) && t ? a.fmt(v / t, 'yuzde') : '—'; })()], ['Müşteri', a.fmt(a.M('[Müşteri Sayısı]', { add }), 'adet')]], spark: col(s, 0), sparkLabel: 'Aylık net satış', note: 'Dokun-basılı tut → Detaya git' }; };

